// Process a big array without blocking the loop
function processInChunks(items, handle, chunk = 1000) {
  return new Promise((resolve) => {
    let i = 0;
    function next() {
      const end = Math.min(i + chunk, items.length);
      for (; i < end; i++) handle(items[i]);
      if (i < items.length) setImmediate(next); // let I/O run between chunks
      else resolve();
    }
    next();
  });
}

