import assert from "node:assert/strict";
import { applyDiscount } from "./math.js";

describe("applyDiscount", () => {
  test("applies a percentage", () => {
    assert.equal(applyDiscount(200, 10), 180);
  });

  test("rejects negative percentages", () => {
    assert.throws(() => applyDiscount(100, -5), /invalid/);
  });

  test("calls the logger once", () => {
    const log = mock.fn();
    applyDiscount(100, 5, { log });
    assert.equal(log.mock.callCount(), 1);
  });
});

