// Leak: grows forever, one entry per unique URL
const cache = new Map();
export async function getPage(url) {
  if (!cache.has(url)) cache.set(url, await render(url));
  return cache.get(url);
}

// Fix: bounded LRU (npm: lru-cache)
import { LRUCache } from "lru-cache";
const pages = new LRUCache({ max: 500, ttl: 60_000 });
export async function getPageSafe(url) {
  let html = pages.get(url);
  if (html === undefined) {
    html = await render(url);
    pages.set(url, html);
  }
  return html;
}

